const jst=new Date(Date.now()+9*3600e3);const todayStr=jst.toISOString().slice(0,10);
function cal(y,m){const first=new Date(Date.UTC(y,m-1,1)).getUTCDay();const days=new Date(Date.UTC(y,m,0)).getUTCDate();let cells='';for(let i=0;i<first;i++)cells+='<td></td>';for(let d=1;d<=days;d++){const ds=`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`;const c=closed.has(ds);cells+=`<td class="${c?'cl':'op'}${ds===todayStr?' td':''}">${d}${c?'<small>休</small>':''}</td>`;if((first+d)%7===0&&d<days)cells+='</tr><tr>'}
return `<div class="cal"><p class="cal-t">${y}年${m}月</p><table><thead><tr><th>日</th><th>月</th><th>火</th><th>水</th><th>木</th><th>金</th><th>土</th></tr></thead><tbody><tr>${cells}</tr></tbody></table></div>`}
function calendars(){const ms=[...new Set(DATA.closed.map(d=>d.slice(0,7)))].filter(k=>k>=todayStr.slice(0,7)).sort().slice(0,3);if(!ms.length)return '<p>営業日は<a href="'+L.net+'" rel="noopener">ネット予約ページ</a>でご確認ください。</p>';const cs=ms.map(k=>cal(+k.slice(0,4),+k.slice(5)));const rest=ms.slice(2).map(k=>`${k.slice(0,4)}年${+k.slice(5)}月`).join('・');return `<div class="cals">${cs.slice(0,2).join('')}</div>${cs.length>2?`<details class="cal-more"><summary>${rest}の営業日もみる</summary><div class="cals">${cs.slice(2).join('')}</div></details>`:''}<p class="note">「休」は休業日です。表示のない日は 9:00〜20:00（最終受付18:00）で営業しています。通常の定休日は毎週月曜・火曜ですが、営業日・休業日は変更になる場合があります。</p>`}
