// 画像最適化：WPが生成済みの縮小版を srcset で出し分け（原寸2.6〜3.3MB→数十KB）。og:image等のmetaは原寸のまま
const VAR={'FLOW-CLOUD-063':[2756,1837],'FLOW-CLOUD-031':[2756,1837],'FLOW-CLOUD-047':[2756,1817],'FLOW-CLOUD-044':[2756,1837],'FLOW-CLOUD-048':[2756,1754],'FLOW-CLOUD-051':[2756,1809]};
const optImgs=h=>h.replace(/<img src="\/cms\/wp-content\/uploads\/2018\/12\/([^"]+)\.jpg"([^>]*)>/g,(m,n,rest)=>{const d=VAR[n];if(!d)return m;const v=w=>`/cms/wp-content/uploads/2018/12/${n}-${w}x${Math.round(d[1]*w/d[0])}.jpg`;const hero=/fetchpriority/.test(rest);if(/class="sm"/.test(rest))return `<img src="${v(300)}" srcset="${v(300)} 300w, ${v(768)} 768w" sizes="250px"${rest}>`;return `<img src="${v(768)}" srcset="${v(300)} 300w, ${v(768)} 768w" sizes="${hero?'(max-width:820px) 100vw, 520px':'(max-width:720px) 100vw, 640px'}"${rest}>`});
const write=(p,html)=>{html=optImgs(html);const f=p==='/'?'index.html':p.replace(/^\//,'')+'index.html';fs.mkdirSync(path.dirname(path.join(OUT,f)),{recursive:true});fs.writeFileSync(path.join(OUT,f),html)};
const JUMP=(a)=>`<nav class="jump" aria-label="メニューの分類">${a.map(x=>`<a href="#${x[0]}">${x[1]}</a>`).join('')}</nav>`;
const sec=(t,inner,cls='',id='')=>{const m=/^<div id="([a-z]+)"><\/div>/.exec(inner);if(m){id=id||m[1];inner=inner.slice(m[0].length)}return `<section class="sec ${cls}"${id?` id="${id}"`:''}><div class="wrap">${t?`<h2>${t}</h2>`:''}${inner}</div></section>`};
const STEPS=sec('ご予約はかんたん3ステップ',`<ol class="steps"><li><b>1</b><h3>メニューを選ぶ</h3><p>お悩みから選ぶ診断や<a href="/menu/">メニュー・料金</a>で、気になるメニューをご確認ください。メニューは、カットまたはシャンプーブローとあわせてのご利用です。</p></li><li><b>2</b><h3>日時を決めて予約</h3><p><a href="${L.net}" rel="noopener">24時間ネット予約</a>のほか、<a href="${L.hp}" rel="noopener">ホットペッパービューティー</a>、お電話（<a href="${L.tel}">${L.telText}</a>）、<a href="${L.line}" rel="noopener">LINE</a>でもご予約・ご相談いただけます。</p></li><li><b>3</b><h3>ご来店</h3><p>南海本線 泉大津駅から徒歩3分。完全予約制の半個室で、お悩みをじっくりうかがいます。</p></li></ol>`);
// 画面いっぱいに流れる帯を入れる章（見出しと注記だけ .wrap の中、帯は全幅）
const wsec=(t,head,wide,foot,cls='')=>`<section class="sec ${cls}"><div class="wrap"><h2>${t}</h2>${head}</div>${wide}<div class="wrap">${foot}</div></section>`;
const castMini=()=>`<ul class="cast cast-mini"><li><a href="/cast/"><img src="/fc/img/cast-fujitsu.jpg" alt="FLOWCLOUDのオーナースタイリスト 藤津一弥" width="480" height="640" loading="lazy"><b>藤津 一弥</b><span>オーナースタイリスト</span></a></li><li><a href="/cast/"><img src="/fc/img/cast-moe.jpg" alt="FLOWCLOUDのスタイリスト もえ" width="480" height="640" loading="lazy"><b>もえ</b><span>スタイリスト</span></a></li><li><a href="/cast/"><img src="/fc/img/cast-takako.jpg" alt="FLOWCLOUDのスタイリスト たかこ（似顔絵イラスト）" width="480" height="593" loading="lazy"><b>たかこ</b><span>スタイリスト</span></a></li><li><a href="/cast/"><div class="ph-none" role="img" aria-label="写真準備中">写真<br>準備中</div><b>あい</b><span>スタイリスト</span></a></li></ul>`;
// ホームの並び順：来店前の不安→価格→店内・人柄→場所・営業日→予約、の順に進めるよう章単位で並べ替える。章が増減したらビルドを止める。
const HOME_ORDER=['こんなお悩みはありませんか？','お悩みから選ぶ、おすすめメニュー','__cta','ヘアスタイルギャラリー','FLOWCLOUDが選ばれる3つの理由','__tick','お客様の声','人気のメニュー','キャスト紹介','通いやすい泉大津駅から徒歩3分','営業日カレンダー','ご予約はかんたん3ステップ','__cta2','よくある質問','お知らせ・ブログ','?動画','Instagram','採用情報・姉妹店'];
function orderHome(body){
 const parts=body.split(/(?=<section class="sec[ "]|<div class="cta">)/).filter(c=>c.trim());
 const map=new Map();let cta1=null;
 for(const c of parts){if(c.startsWith('<div class="cta">')){cta1=c;continue}const k=(c.match(/<h2>(.*?)<\/h2>/)||[])[1];if(!k||map.has(k))throw new Error('home chunk key: '+k);map.set(k,c)}
 const out=[];
 for(const k of HOME_ORDER){if(k==='__cta'){out.push(cta1);continue}if(k==='__cta2'){out.push(cta('ご来店の日が決まったら'));continue}if(k==='__tick'){out.push(TICK);continue}if(k[0]==='?'){const kk=k.slice(1);if(map.has(kk)){out.push(map.get(kk));map.delete(kk)}continue}if(!map.has(k))throw new Error('missing home chunk: '+k);out.push(map.get(k));map.delete(k)}
 if(map.size)throw new Error('unplaced home chunks: '+[...map.keys()].join(','));
 let n=0;return out.map(c=>c.startsWith('<section class="sec')?c.replace(/^<section class="sec([^"]*)"/,(m,cl)=>`<section class="sec${cl.split(/\s+/).filter(x=>x&&x!=='alt').map(x=>' '+x).join('')}${n++%2?' alt':''}"`):c).join('');
}
// ページ末の「つぎは、こちらもどうぞ」：次に見るページを3つ提案（回遊・滞在時間・予約への流れ／内部リンク）。文言は各ページの冒頭文から。
const NXC={'/style/':['ヘアスタイル','ロング・ボブ・ショート・カラーの仕上がり写真を、種類別にご覧いただけます。'],'/menu/':['メニュー・料金','髪質改善・カラー・ヘッドスパなどの料金の目安をご覧いただけます。'],'/coupon/':['クーポン','ホットペッパービューティー掲載のクーポンをご案内します。'],'/voice/':['お客様の声','ホットペッパービューティーに寄せられた★5の口コミを抜粋してご紹介します。'],'/first/':['初めてのお客様へ','「わたしのプチ別荘」のような、完全予約・半個室の美容室です。'],'/cast/':['キャスト紹介','お客様一人ひとりに合った施術で、みなさまの笑顔とキレイをお手伝いします。'],'/hair-care-40-50/':['40代・50代の髪','パサつき・うねり・ボリューム不足。半個室で、髪質改善とヘッドスパをご提案します。'],'/hair-quality/':['髪質改善メニュー','髪質改善ストレート・パーマ・ストパーマ・シスキュアからご提案します。'],'/straight/':['髪質改善ストレート','クセ・うねり・広がりが気になる方へ。縮毛矯正のご相談はこちら。'],'/color/':['カラー・白髪染め','白髪や退色のお悩みを、カウンセリングでうかがってからご提案します。'],'/headspa/':['ヘッドスパ','真っ暗な空間で、頭皮と髪、そして心まで整えるひとときを。'],'/men/':['メンズカット・ヘッドスパ','男性のお客様も、半個室で周りを気にせずに。カットとヘッドスパをご案内します。'],'/company/':['アクセス','南海本線「泉大津駅」徒歩3分。住所・営業時間はこちら。'],'/area/':['対応エリア','泉大津はもちろん、岸和田・高石・和泉・堺などからもお越しいただけます。'],'/faq/':['よくある質問','ご予約・営業時間・アクセス・メニューについてお答えします。'],'/cota-products/':['コタ製品','コタ（COTA）の全商品を取り扱い、店頭で販売しています。']};
const NX={'/menu/':['/first/','/voice/','/hair-care-40-50/'],'/coupon/':['/menu/','/first/','/company/'],'/voice/':['/style/','/menu/','/first/'],'/first/':['/cast/','/menu/','/company/'],'/cast/':['/style/','/menu/','/first/'],'/style/':['/menu/','/voice/','/first/'],'/hair-care-40-50/':['/style/','/hair-quality/','/headspa/'],'/hair-quality/':['/style/','/menu/','/voice/'],'/straight/':['/style/','/hair-quality/','/menu/'],'/color/':['/style/','/menu/','/voice/'],'/headspa/':['/menu/','/men/','/coupon/'],'/men/':['/menu/','/headspa/','/first/'],'/company/':['/menu/','/first/','/coupon/'],'/area/':['/company/','/first/','/menu/'],'/faq/':['/first/','/menu/','/coupon/'],'/cota-products/':['/menu/','/hair-quality/','/first/']};
const nextSec=p=>{const ks=NX[p]||(p.startsWith('/salon-blog/')&&p!=='/salon-blog/'?['/menu/','/first/','/voice/']:null);if(!ks)return '';return sec('つぎは、こちらもどうぞ',`<ul class="nx">${ks.map(k=>`<li><a class="nx-c" href="${k}"><b>${NXC[k][0]}</b><span>${NXC[k][1]}</span><i aria-hidden="true">→</i></a></li>`).join('')}</ul>`,'nx-sec')};
const faqLD=(items)=>({"@type":"FAQPage","mainEntity":items.map(([q,a])=>({"@type":"Question","name":q,"acceptedAnswer":{"@type":"Answer","text":a}}))});
const faqHtml=items=>`<div class="faq">${items.map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</div>`;
const worries=['とにかくダメージで困っている','クセやうねりでおさまりが悪い','バサバサで広がる','ペたんとなりボリュームが出ない'.replace('ペ','ぺ'),'てっぺんの毛が薄くなってきた','ハチがはる','まとまりが悪くボリュームが出すぎる','カラーの退色が気になる','髪がゴワゴワする'];
// HOME
write('/',page({path:'/',hero:true,title:'泉大津の美容院・美容室 FLOWCLOUD（フロウクラウド）｜髪質改善・ヘッドスパ｜完全予約制',desc:'泉大津駅徒歩3分の美容院・美容室FLOWCLOUD（フロウクラウド）。完全予約の会員制・半個室。真っ暗な空間で癒しの映像を見ながら、トリートメント＆ヘッドスパで髪質改善・頭皮改善。24時間ネット予約OK。',h1:'素髪から、きれいに。<br>泉大津の完全予約・会員制美容室',lead:'パサつき・うねり・ボリューム不足。大人の髪のお悩みに、半個室の静かな空間で一人ひとり向き合います。岸和田・高石・和泉・堺・泉佐野・貝塚など泉州・南大阪からも通いやすい立地です。',extra:[faqLD(faq)],
body:
sec('こんなお悩みはありませんか？',`<ul class="worry">${worries.map(w=>`<li>${w}</li>`).join('')}</ul><p>FLOWCLOUDは、髪質改善ストレート・髪質改善パーマ・自社開発トリートメント「シスキュア」・ヘッドスパなど、髪と頭皮に向き合うメニューをそろえています。</p><p><a class="more" href="/hair-quality/">髪質改善メニューの選び方と料金を見る →</a>　<a class="more" href="/hair-care-40-50/">40代・50代の髪のお悩み →</a>　<a class="more" href="/color/">カラー・白髪染めのご相談 →</a></p>`)+
sec('お悩みから選ぶ、おすすめメニュー',QZ('fc','いま、いちばん気になるのは？','お悩みをタップすると、おすすめのメニューをご案内します。',QITEMS_FC,'※料金は税込の目安です。メニューはカットまたはシャンプーブローとあわせてのご利用で、長さにより料金が変わるものがあります。仕上がりには個人差があります。'),'alt')+
cta('今すぐ予約する')+
wsec('ヘアスタイルギャラリー','<p class="gm-lead">公式Instagramに掲載した、最近の仕上がりです。</p>',GAL2.home(),`<p class="gm-more"><a class="btn b-hp" href="/style/">ヘアスタイルをもっと見る</a></p><p class="note gm-note">${GAL_NOTE}</p>`)+
sec('FLOWCLOUDが選ばれる3つの理由',`<div class="g3"><article><img src="${IMG('FLOW-CLOUD-063')}" alt="仕切りのある半個室の店内" loading="lazy" width="1024" height="768"><h3>1. 他の人が気にならない半個室</h3><p>外から見えにくい店内は一席ずつ仕切りがあり、靴を脱いでスリッパで過ごせる居心地の良い空間です。</p></article><article><img src="${IMG('FLOW-CLOUD-031')}" alt="照明を落とした落ち着いたシャンプー空間" loading="lazy" width="1024" height="768"><h3>2. 究極の癒しのシャンプー空間</h3><p>真っ暗な空間で、癒しの音楽と映像を感じながら、フルフラットのベッドで最高のシャンプー・ヘッドスパをお届けします。</p></article><article><img src="${IMG('FLOW-CLOUD-047')}" alt="カウンセリングに使う明るい店内のテーブル席" loading="lazy" width="1024" height="768"><h3>3. 会員制の完全予約</h3><p>無駄な待ち時間はありません。一人ひとりの時間を大切に、悩みの解決と理想の実現をめざします。</p></article></div>`)+
sec('人気のメニュー',`<div class="g3 pm"><a href="/menu/#rehair"><h3>髪質改善ストレート</h3><p>120分〜／¥16,500〜</p></a><a href="/menu/#rehair"><h3>髪質改善パーマ</h3><p>120分〜／¥16,500〜</p></a><a href="/menu/#rehair"><h3>シスキュア（トリートメント）</h3><p>20分／¥3,850</p></a><a href="/menu/#spa"><h3>リフトアップヘッドスパ</h3><p>30分／¥5,500</p></a><a href="/menu/#spa"><h3>炭酸ヘッドマッサージ</h3><p>10分／¥2,200</p></a><a href="/menu/#cut"><h3>カット（シャンプーブロー込）</h3><p>50分／¥5,500</p></a></div><p class="note">※長さによって料金が変わるメニューがあります。クーポンは<a href="${L.coupon}" rel="noopener">ホットペッパービューティー</a>で最新情報をご確認ください。<a href="/menu/">全メニュー・料金へ</a></p>`)+
sec('通いやすい泉大津駅から徒歩3分',`<div class="two"><img src="${IMG('FLOW-CLOUD-001-1024x733')}" alt="FLOWCLOUDの外観。緑の扉が目印" loading="lazy" width="1024" height="733"><div><p>南海本線「泉大津駅」から徒歩3分。<strong>岸和田・高石・羽衣・堺・春木・貝塚・泉佐野</strong>など南海本線沿線の方はもちろん、<strong>和泉・和泉府中・和泉中央</strong>方面からもお越しいただけます。</p><p>〒595-0026 大阪府泉大津市東雲町1-20<br>TEL <a href="${L.tel}">${L.telText}</a></p><p><a class="more" href="/area/">対応エリアとアクセス →</a></p></div></div>`)+
sec('お客様の声',rateBox(RT,HPREV,L.gbp)+revCards(3)+'<p><a class="more" href="/voice/">お客様の声をもっと見る →</a></p>')+sec('お知らせ・ブログ',postList(3)+'<p><a class="more" href="/salon-blog/">お知らせ・ブログ一覧 →</a>　<a href="/news_blog/">過去のお知らせ・ブログ</a></p>')+sec('営業日カレンダー',calendars(),'alt')+STEPS+((DATA.videos||[]).length?videos():'')+sec('Instagram',insta()+vlinks)+sec('よくある質問',faqHtml(faq.slice(0,6))+'<p><a class="more" href="/faq/">すべての質問を見る →</a></p>','alt')+
sec('採用情報・姉妹店',`<p>FLOWCLOUDの運営会社・株式会社行雲流水では、美容師・アシスタント・パートなどを募集しています。見学・ご相談も受け付けています。</p><p><a class="btn b-net" href="${L.recruit}">採用サイト（ko-un-ryu-sui.com）を見る</a>　<a class="btn b-hp" href="${L.glow}" rel="noopener">姉妹店 glow（グロウ）</a></p>`,'alt')+sec('キャスト紹介',castMini()+`<p>オーナースタイリストの藤津一弥は、2007年11月に忠岡で10坪の完全予約のプライベートサロンを開業。2015年にトリートメントメニュー「シスキュア」を開発し、2018年4月に泉大津へ拡張移転しました。国際美容ライセンスを保持しています。</p><p><a class="more" href="/cast/">キャスト紹介 →</a></p>`)
}));

write('/coupon/',page({path:'/coupon/',title:'クーポン｜泉大津の美容室 FLOWCLOUD｜髪質改善・ヘッドスパ・カラー',desc:'泉大津の美容室FLOWCLOUDのクーポン一覧（ホットペッパービューティー掲載分・'+DATA.asOf+'時点）。髪質改善、頭皮改善、炭酸ヘッドスパ、トリートメントなど。',h1:'クーポン',lead:'ホットペッパービューティーに掲載中のクーポンのご案内です（'+DATA.asOf+'時点）。クーポンは随時切り替わりますので、最新は予約ページでご確認ください。',crumbs:[['/coupon/','クーポン']],
body:sec('おすすめクーポン',`<div class="cps">${DATA.coupons.map(c=>`<article class="cp"><span class="tag">${c.tag}</span><h3>${esc(c.t)}</h3><p class="cp-p">${c.p}</p><p class="note">${esc(c.note)}</p><p><a class="btn b-net" href="${L.net}" rel="noopener">ネット予約へ</a> <a class="btn b-hp" href="${L.coupon}" rel="noopener">ホットペッパーで見る</a></p></article>`).join('')}</div><p class="note">${DATA.couponNote}価格は税込です。</p>`)+`<div class="wrap">${cta('クーポンを使って予約')}</div>`}));
