const f45=[['40代・50代でも髪質改善はできますか？','髪の状態をカウンセリングしたうえで、髪質改善ストレート・髪質改善パーマ・トリートメントなどから合うメニューをご提案します。お悩みはご予約時にもお伝えいただけます。'],['白髪染めやカラーの退色も相談できますか？','はい。根元カラー・全体カラー・ホイルワークなどのメニューがあります。カラーの退色が気になる方もご相談ください。'],['頭皮のケアもお願いできますか？','リフトアップヘッドスパ、疲れ目改善ヘッドスパ、炭酸ヘッドマッサージなど複数のヘッドスパメニューがあります。']];
write('/hair-care-40-50/',page({path:'/hair-care-40-50/',title:'40代・50代の髪質改善｜パサつき・うねり・ボリューム｜泉大津の美容室 FLOWCLOUD',desc:'40代・50代の髪のお悩み（パサつき・うねり・ボリューム不足・カラーの退色）に。泉大津の完全予約制美容室FLOWCLOUDの髪質改善ストレート・パーマ・シスキュア・ヘッドスパをご案内。',h1:'40代・50代の素髪を、もっときれいに',lead:'年齢を重ねた髪の「パサつき」「うねり」「ボリューム不足」。FLOWCLOUDは、半個室の落ち着いた空間で、髪質改善とヘッドスパをご提案する完全予約制の美容室です。',crumbs:[['/hair-care-40-50/','40代・50代の髪質改善']],extra:[faqLD(f45)],
body:sec('こんなお悩みの方へ',`<ul class="worry">${worries.map(w=>`<li>${w}</li>`).join('')}<li>髪が細くて柔らかく量が少ない</li><li>髪が太くて硬くて量が多い</li></ul><p>お悩みは一人ひとり違います。カウンセリングで髪の状態をうかがい、合うメニューをご提案します。</p>`)+
sec('おすすめのメニュー',`<div class="g3 pm"><a href="/menu/#rehair"><h3>髪質改善ストレート</h3><p>クセ・うねりが気になる方に。120分〜／¥16,500〜</p></a><a href="/menu/#rehair"><h3>髪質改善パーマ</h3><p>ボリュームやまとまりに。120分〜／¥16,500〜</p></a><a href="/menu/#rehair"><h3>シスキュア</h3><p>当店オリジナルのトリートメント。20分／¥3,850</p></a><a href="/menu/#spa"><h3>リフトアップヘッドスパ</h3><p>30分／¥5,500</p></a><a href="/menu/#spa"><h3>疲れ目改善ヘッドスパ</h3><p>25分／¥4,400</p></a><a href="/color/"><h3>カラー・ホイルワーク</h3><p>根元カラー45分〜／¥6,600〜</p></a></div><p class="note">※長さによって料金が変わります。施術時間・料金は目安です。</p>`,'alt')+
sec('安心して通える理由',`<ul class="ul"><li><b>半個室</b>：一席ずつ仕切りがあり、他のお客様が気になりにくい空間です。</li><li><b>完全予約制</b>：待ち時間なく、ご自身のための時間を過ごせます。</li><li><b>癒しのシャンプー</b>：真っ暗な空間でフルフラットのベッドをご用意しています。</li><li><b>駅から徒歩3分</b>：南海本線 泉大津駅が最寄りです。</li></ul><p><a class="more" href="/hair-quality/">髪質改善メニューの選び方と料金 →</a></p>`)+
`<div class="wrap">${cta('髪のお悩み相談・ご予約')}</div>`+sec('よくある質問',faqHtml(f45),'alt')
}));
